rules.source:
rule "GeoIP Lookup Source IP"
when
  has_field("src_ip") AND
  ! cidr_match("10.0.0.0/8", to_ip($message.src_ip)) AND
  ! cidr_match("172.16.0.0/12", to_ip($message.src_ip)) AND
  ! cidr_match("192.168.0.0/16", to_ip($message.src_ip))
then
  let geo = geoip_lookup(to_ip($message.src_ip));
  set_field("src_geo_country", geo["country"].iso_code);
  set_field("src_geo_city", geo["city"].names.en);
  set_field("src_geo_latitude", geo["location"].latitude);
  set_field("src_geo_longitude", geo["location"].longitude);
end

rule "GeoIP Lookup Destination IP"
when
  has_field("dst_ip") AND
  ! cidr_match("10.0.0.0/8", to_ip($message.dst_ip)) AND
  ! cidr_match("172.16.0.0/12", to_ip($message.dst_ip)) AND
  ! cidr_match("192.168.0.0/16", to_ip($message.dst_ip))
then
  let geo = geoip_lookup(to_ip($message.dst_ip));
  set_field("dst_geo_country", geo["country"].iso_code);
  set_field("dst_geo_city", geo["city"].names.en);
  set_field("dst_geo_latitude", geo["location"].latitude);
  set_field("dst_geo_longitude", geo["location"].longitude);
end
